package com.example.discussions.model;
import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="discussions") public class Discussion {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false,length=200) public String title;@Column(nullable=false,columnDefinition="text") public String body;@Enumerated(EnumType.STRING) public Status status=Status.OPEN;@ManyToOne(optional=false) @JoinColumn(name="author_id") public User author;@ManyToOne(optional=false) @JoinColumn(name="category_id") public Category category;@Column(name="created_at",nullable=false) public Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) public Instant updatedAt=Instant.now();@OneToMany(mappedBy="discussion",cascade=CascadeType.ALL) @JsonIgnore public List<Comment> comments=new ArrayList<>();@OneToMany(mappedBy="discussion",cascade=CascadeType.ALL) @JsonIgnore public Set<Vote> votes=new HashSet<>();@OneToMany(mappedBy="discussion",cascade=CascadeType.ALL) @OrderBy("createdAt ASC") public List<DiscussionAction> actions=new ArrayList<>();@PreUpdate void update(){updatedAt=Instant.now();}public enum Status{OPEN,PLANNED,DONE,CLOSED,CANCELLED}}
